using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

const int WarmupIterations = 50;
const int MeasureIterations = 200;

var small = new TextAnalyzer("The quick brown fox jumps over the lazy dog near the river bank");
var rng = new Random(42);
var words = new string[10_000];
for (int i = 0; i < words.Length; i++)
{
    int len = rng.Next(1, 15);
    var chars = new char[len];
    for (int j = 0; j < len; j++)
        chars[j] = (char)('a' + rng.Next(26));
    words[i] = new string(chars);
}
var large = new TextAnalyzer(string.Join(' ', words));

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"{"Method",-35} {"Mean (ns)",12} {"StdDev (ns)",12}");
Console.WriteLine(new string('-', 61));

Bench("AverageWordLength_Small", () => small.AverageWordLength());
Bench("AverageWordLength_Large", () => large.AverageWordLength());
Bench("WordLengthHistogram_Small", () => small.WordLengthHistogram());
Bench("WordLengthHistogram_Large", () => large.WordLengthHistogram());
Bench("UniqueWordCount_Small", () => small.UniqueWordCount());
Bench("UniqueWordCount_Large", () => large.UniqueWordCount());

[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Func<object?> action)
{
    // warmup
    for (int i = 0; i < WarmupIterations; i++) action();

    var times = new double[MeasureIterations];
    var sw = new Stopwatch();
    for (int i = 0; i < MeasureIterations; i++)
    {
        sw.Restart();
        action();
        sw.Stop();
        times[i] = sw.Elapsed.TotalNanoseconds;
    }
    double mean = times.Average();
    double stddev = Math.Sqrt(times.Select(t => (t - mean) * (t - mean)).Average());
    Console.WriteLine($"{name,-35} {mean,12:F1} {stddev,12:F1}");
}

// overloads to box value types
static object? Wrap(double v) => (object)v;
static object? Wrap(int v) => (object)v;
static object? Wrap(object v) => v;

